public sealed class QueueLease(string messageId)
{
    public string MessageId { get; } = messageId;
    public DateTimeOffset LockedUntil { get; set; }
        = DateTimeOffset.UtcNow.AddSeconds(30);
}

var a = new QueueLease("msg-42");
var b = a; // copies the reference, not the object
b.LockedUntil = DateTimeOffset.UtcNow.AddMinutes(1);
// a.LockedUntil is also updated — same object

public sealed class OrderProcessor
{
    public void Process(string orderId) => Validator.EnsureNotEmpty(orderId);

    private static class Validator
    {
        public static void EnsureNotEmpty(string value)
        {
            if (string.IsNullOrEmpty(value))
                throw new ArgumentException("orderId required");
        }
    }
}

